void SS_igaw_pc_init_function(	PC_ref 	*SS_pc_xeos,
							    int 	 iss,
							    char 	*name,
							    global_variable gv			){	
						 
	if      (strcmp( name, "bi")  == 0 ){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_bi_pc_xeos; 		}
	else if (strcmp( name, "fper")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_fper_pc_xeos;      }
	else if (strcmp( name, "cd")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_cd_pc_xeos; 		}
	else if (strcmp( name, "cpx") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_cpx_pc_xeos; 		}
	else if (strcmp( name, "ep")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_ep_pc_xeos; 		}
	else if (strcmp( name, "fl")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_fl_pc_xeos; 		}
	else if (strcmp( name, "g")   == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_g_pc_xeos; 		}
	else if (strcmp( name, "amp")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_amp_pc_xeos; 		}
	else if (strcmp( name, "ilm") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_ilm_pc_xeos; 		}
	else if (strcmp( name, "liq") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_liq_pc_xeos; 		}
	else if (strcmp( name, "mu")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_mu_pc_xeos; 		}
	else if (strcmp( name, "ol")  == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_ol_pc_xeos; 		}
	else if (strcmp( name, "opx") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_opx_pc_xeos; 		}
	else if (strcmp( name, "fsp") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_fsp_pc_xeos; 	    }
	else if (strcmp( name, "spl") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_spl_pc_xeos; 		}
	else if (strcmp( name, "chl") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_chl_pc_xeos; 		}
	else if (strcmp( name, "kals") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_kals_pc_xeos; 		}
	else if (strcmp( name, "mel") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_mel_pc_xeos; 		}
	else if (strcmp( name, "lct") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_lct_pc_xeos; 		}
	else if (strcmp( name, "nph") == 0){
		SS_pc_xeos[iss].ss_pc_xeos  = igaw_nph_pc_xeos; 		}
	else{
		printf("\nsolid solution '%s' is not in the database, cannot be initiated\n", name);	
	}	
}
